1	import type {AddressInfo} from 'node:net';
2	import {WebSocket} from 'ws';
3	import type {Express} from 'express';
4	import {createServer} from './createServer.js';
5	import type {HalServer, HalServerOptions} from './createServer.js';
6	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
7	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
8	import type {MessageChunk} from '../types/ai.js';
9	import type {ChatSession} from '../types/session.js';
10	import type {SessionStore} from '../types/sessionStore.js';
11	
12	// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.
13	
14	const servers: Array<{stop: () => Promise<void>}> = [];
15	const clients: WebSocket[] = [];
16	
17	/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
18	export const answeringOrchestrator: ChatOrchestrator = {
19	  processMessage: async () => 'hi',
20	  async *processMessageStream(): AsyncGenerator<MessageChunk> {
21	    yield {type: 'text', text: 'hi'};
22	    yield {type: 'stop', stopReason: 'end_turn'};
23	  },
24	};
25	
26	/** Starts an engine on an ephemeral port and returns the URL a client should open. */
27	export async function startEngine(
28	  sessionStore: SessionStore,
29	  onDisconnect?: (sessionId: string) => void
30	): Promise<string> {
31	  const {url} = await startEngineWith({sessionStore, onDisconnect});
32	  return url;
33	}
34	
35	/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
36	export async function startEngineWith(
37	  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
38	): Promise<{url: string; hal: HalServer}> {
39	  const hal = createServer({
40	    app: (() => undefined) as unknown as Express,
41	    wsAuth: async () => ({id: 'u1'}),
42	    orchestrator: answeringOrchestrator,
43	    ...options,
44	  });
45	  await hal.start(0);
46	  servers.push(hal);
47	  const {port} = hal.server.address() as AddressInfo;
48	  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
49	}
50	
51	/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
52	export function connectClient(url: string, token = 't'): WebSocket {
53	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
54	  clients.push(client);
55	  return client;
56	}
57	
58	/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
59	export function deferred(): {until: Promise<void>; release: () => void} {
60	  let release = (): void => undefined;
61	  const until = new Promise<void>(resolve => {
62	    release = resolve;
63	  });
64	  return {until, release};
65	}
66	
67	/** Resolves with every frame type seen up to and including the first `until` frame. */
68	export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
69	  const seen: string[] = [];
70	  return new Promise<string[]>(resolve => {
71	    client.on('message', raw => {
72	      const {type} = JSON.parse(String(raw)) as {type: string};
73	      seen.push(type);
74	      if (type === until) resolve(seen);
75	    });
76	  });
77	}
78	
79	/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
80	export function askOnOpen(
81	  url: string,
82	  {until = 'stream_end', token}: {until?: string; token?: string} = {}
83	): {client: WebSocket; finished: Promise<string[]>} {
84	  const client = connectClient(url, token);
85	  const finished = framesUntil(client, until);
86	  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
87	  return {client, finished};
88	}
89	
90	/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
91	export function announcedId(client: WebSocket): () => string {
92	  let sessionId = '';
